WITH filtered AS (SELECT *, CASE WHEN budget >= 3835000 THEN 'High' WHEN budget >= 1797000 THEN 'Medium' ELSE 'Low' END AS budget_band FROM departments WHERE dept_name IS NOT DISTINCT FROM 'Engineering' AND budget < 3933000), matched_keys AS (SELECT location, dept_name FROM filtered INTERSECT SELECT location, dept_name FROM departments WHERE budget <= 2783000), verified AS (SELECT s.* FROM filtered s JOIN matched_keys k ON s.location = k.location AND s.dept_name = k.dept_name), valid AS (SELECT id, dept_name, location, budget_band, COALESCE(budget, 0) AS budget_filled FROM verified WHERE location IS NOT NULL), eligible AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.is_remote)), eligible_departments AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.full_name IS NOT NULL)), enriched AS (SELECT *, DENSE_RANK() OVER (PARTITION BY dept_name ORDER BY budget_filled NULLS FIRST) AS budget_filled_dense_rank, AVG(budget_filled) OVER (PARTITION BY location) AS location_avg_budget_filled, RANK() OVER (PARTITION BY location ORDER BY budget_filled DESC) AS budget_filled_rank, AVG(budget_filled) OVER (PARTITION BY location) AS location_avg_budget_filled_2, AVG(budget_filled) OVER (PARTITION BY location) AS location_avg_budget_filled_3 FROM eligible_departments), not_flagged AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND LOWER(TRIM(c.email)) = 'jack@startup.io')) SELECT budget_filled, budget_filled_dense_rank, location_avg_budget_filled, location_avg_budget_filled_2, location_avg_budget_filled_3 FROM not_flagged ORDER BY location_avg_budget_filled_3 DESC
